package microdesc

import (
	"bytes"
	"crypto/sha256"
	"encoding/base64"
	"os"
	"strings"
	"testing"

	"github.com/robogg133/gonion/pkg/common"
)

// tor-test-md.fixture is test_md2_25 from Tor's official test_microdesc.c,
// maint-0.4.7 (Tor Project, BSD-3-Clause). It was generated by chutney.
// https://raw.githubusercontent.com/torproject/tor/maint-0.4.7/src/test/test_microdesc.c
func TestOfficialMicrodescriptor(t *testing.T) {
	data, err := os.ReadFile("tor-test-md.fixture")
	if err != nil {
		t.Fatal(err)
	}
	digest := sha256.Sum256(data)
	d := base64.RawStdEncoding.EncodeToString(digest[:])
	out, err := (Parser{}).Parse(bytes.NewReader(data), []string{d, d})
	if err != nil {
		t.Fatal(err)
	}
	if len(out) != 2 || out[0] == nil || out[1] == nil || len(out[0].NTorOnionKey) != 32 || !out[0].ExitRules.IsAllowed(443) {
		t.Fatal("official descriptor not hydrated")
	}
	for name, input := range map[string][]byte{"truncated": data[:len(data)-1], "added-newline": append(bytes.Clone(data), '\n'), "crlf": bytes.ReplaceAll(data, []byte("\n"), []byte("\r\n")), "corrupt": bytes.Replace(data, []byte("accept"), []byte("reject"), 1)} {
		t.Run(name, func(t *testing.T) {
			got, err := (Parser{}).Parse(bytes.NewReader(input), []string{d})
			if err == nil && got[0] != nil {
				t.Fatal("accepted altered digest bytes")
			}
		})
	}
	for name, input := range map[string][]byte{
		"junk before PEM": bytes.Replace(data, []byte("onion-key\n"), []byte("onion-key\njunk\n"), 1),
		"junk inside PEM": bytes.Replace(data, []byte("-----BEGIN RSA PUBLIC KEY-----\n"), []byte("-----BEGIN RSA PUBLIC KEY-----\njunk\n"), 1),
	} {
		t.Run(name, func(t *testing.T) {
			check := sha256.Sum256(input)
			name := base64.RawStdEncoding.EncodeToString(check[:])
			if _, err := common.ParseMicrodescriptor(input, name); err == nil {
				t.Fatal("trust parser accepted malformed PEM framing")
			}
			if _, err := (Parser{}).Parse(bytes.NewReader(input), []string{name}); err == nil {
				t.Fatal("batch parser accepted malformed PEM framing")
			}
		})
	}
	for _, suffix := range []string{"family $\n", "family-ids missing-colon\n", "id ed25519 AA\n", "p accept 1-999999999\n", strings.Repeat("x", 65536) + "\n"} {
		input := append(bytes.Clone(data), []byte(suffix)...)
		dig := sha256.Sum256(input)
		if _, err := (Parser{}).Parse(bytes.NewReader(input), []string{base64.RawStdEncoding.EncodeToString(dig[:])}); err == nil {
			t.Fatal("accepted malformed descriptor")
		}
	}
}

// TestParseFullRequest fills the found descriptor at every position it was
// requested in, out of a request of MaxDigests digests, and rejects larger
// requests.
func TestParseFullRequest(t *testing.T) {
	data, err := os.ReadFile("tor-test-md.fixture")
	if err != nil {
		t.Fatal(err)
	}
	sum := sha256.Sum256(data)
	found := base64.RawStdEncoding.EncodeToString(sum[:])

	digests := make([]string, MaxDigests)
	for i := range digests {
		other := sha256.Sum256([]byte{byte(i), byte(i >> 8)})
		digests[i] = base64.RawStdEncoding.EncodeToString(other[:])
	}
	digests[3], digests[MaxDigests-1] = found, found

	out, err := (Parser{}).Parse(bytes.NewReader(data), digests)
	if err != nil {
		t.Fatal(err)
	}
	for i, md := range out {
		want := i == 3 || i == MaxDigests-1
		if (md != nil) != want {
			t.Fatalf("descriptor %d present=%v", i, md != nil)
		}
	}

	if _, err := (Parser{}).Parse(bytes.NewReader(data), append(digests, found)); err == nil {
		t.Fatal("request above the limit accepted")
	}
}

// TestOnionKeyObjectOptional parses microdescriptors without the obsolete TAP
// key object, as consensus method 37 generates them (dir-spec: the onion-key
// item is required, its object is optional), and still rejects an object
// that doesn't follow the onion-key item.
func TestOnionKeyObjectOptional(t *testing.T) {
	data, err := os.ReadFile("tor-test-md.fixture")
	if err != nil {
		t.Fatal(err)
	}
	begin := bytes.Index(data, []byte("-----BEGIN RSA PUBLIC KEY-----\n"))
	endMarker := []byte("-----END RSA PUBLIC KEY-----\n")
	end := bytes.Index(data, endMarker) + len(endMarker)
	if begin < 0 || end <= begin {
		t.Fatal("fixture has no onion key object")
	}
	noKey := append(bytes.Clone(data[:begin]), data[end:]...)
	if !bytes.HasPrefix(noKey, []byte("onion-key\nntor-onion-key ")) {
		t.Fatalf("unexpected fixture layout: %q", noKey[:40])
	}

	digestOf := func(b []byte) string {
		sum := sha256.Sum256(b)
		return base64.RawStdEncoding.EncodeToString(sum[:])
	}
	for name, parse := range map[string]func([]byte) (*common.Microdesc, error){
		"trust": func(b []byte) (*common.Microdesc, error) {
			return common.ParseMicrodescriptor(b, digestOf(b))
		},
		"batch": func(b []byte) (*common.Microdesc, error) {
			out, err := (Parser{}).Parse(bytes.NewReader(b), []string{digestOf(b)})
			if err != nil {
				return nil, err
			}
			return out[0], nil
		},
	} {
		t.Run(name, func(t *testing.T) {
			md, err := parse(noKey)
			if err != nil || md == nil {
				t.Fatalf("method 37 descriptor rejected: %v", err)
			}
			if md.OnionKey != nil || len(md.NTorOnionKey) != 32 || !md.ExitRules.IsAllowed(443) {
				t.Fatal("method 37 descriptor parsed wrong")
			}

			// The object after another item is malformed.
			stray := append(bytes.Clone(noKey), data[begin:end]...)
			if md, err := parse(stray); err == nil && md != nil {
				t.Fatal("stray object accepted")
			}

			// The onion-key item itself stays mandatory.
			noItem := bytes.TrimPrefix(noKey, []byte("onion-key\n"))
			if md, err := parse(noItem); err == nil && md != nil {
				t.Fatal("descriptor without onion-key item accepted")
			}
		})
	}
}

// TestFormatWithoutOnionKey writes the onion-key item even without a key, so
// the result parses again.
func TestFormatWithoutOnionKey(t *testing.T) {
	ntor := bytes.Repeat([]byte{7}, 32)
	out, err := (Parser{}).Format([]*common.Microdesc{{NTorOnionKey: ntor}})
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.HasPrefix(out, []byte("onion-key\nntor-onion-key ")) {
		t.Fatalf("unexpected output %q", out)
	}
	block := bytes.TrimSuffix(out, []byte("\n"))
	block = append(block, '\n')
	sum := sha256.Sum256(block)
	md, err := common.ParseMicrodescriptor(block, base64.RawStdEncoding.EncodeToString(sum[:]))
	if err != nil || !bytes.Equal(md.NTorOnionKey, ntor) {
		t.Fatalf("formatted descriptor doesn't parse: %v %q", err, out)
	}
}
